package com.safarilanka.config;
import com.safarilanka.model.*; import com.safarilanka.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import java.math.*; import java.time.*; import java.util.*;
@Configuration
public class DataSeeder {
 @Bean CommandLineRunner seed(UserRepository users,SafariPackageRepository packages,VehicleRepository vehicles,BookingRepository bookings,VisitorRepository visitors,PaymentRepository payments,PermitRepository permits,TripAssignmentRepository assignments,SystemSettingRepository settings,PasswordEncoder encoder){return args->{
  User tourist=user(users,encoder,"Demo Tourist","tourist@safarilanka.lk","Tourist@123",Role.TOURIST,"0771000001"); tourist.setAddress("Colombo, Sri Lanka"); tourist.setCountry("Sri Lanka"); tourist.setPreferredCurrency("LKR"); tourist.setGender("MALE"); tourist.setBirthDate(LocalDate.of(2004,1,1)); tourist.setIdentityType("NIC"); tourist.setIdentityNumber("200012345678"); users.save(tourist);
  User operator=user(users,encoder,"Safari Operations Manager","operator@safarilanka.lk","Operator@123",Role.SAFARI_OPERATOR,"0771000002");
  User guide=user(users,encoder,"Senior Safari Guide","guide@safarilanka.lk","Guide@123",Role.SAFARI_GUIDE,"0771000003"); guide.setQualifications("Certified Naturalist; First Aid; Yala Block I experience");guide.setLanguages("English, Sinhala");guide.setLicenseNumber(null);users.save(guide);
  User driver=user(users,encoder,"Yala Jeep Driver","driver@safarilanka.lk","Driver@123",Role.JEEP_DRIVER,"0771000004");driver.setLicenseNumber("B1234567");users.save(driver);
  user(users,encoder,"Authorized Park Gate Officer","park@safarilanka.lk","Park@123",Role.PARK_OFFICER,"0771000005");
  user(users,encoder,"Finance & Administration Manager","finance@safarilanka.lk","Finance@123",Role.FINANCE_MANAGER,"0771000006");
  user(users,encoder,"System Administrator","admin@safarilanka.lk","Admin@123",Role.SYSTEM_ADMIN,"0771000007");
  if(settings.count()==0){setting(settings,"park.name","Yala National Park","Prototype park scope");setting(settings,"park.gate","Yala Palatupana Gate","Default permit validation gate");setting(settings,"payment.mode","SIMULATED","Academic payment mode - no real gateway");setting(settings,"notifications.enabled","true","In-app notification feature flag");setting(settings,"academic.disclaimer","This is an academic prototype and not an official DWC system.","Required prototype disclaimer");}
  ensureSetting(settings,"chatbot.enabled","true","Tourist Kavi chatbot feature flag controlled by System Administration");
  if(packages.count()==0){
   packages.save(pkg("Yala Dawn Leopard Quest","Early-morning safari focused on Yala Block I habitats and responsible leopard observation.","Block I - Palatupana","05:30 - 10:30",new BigDecimal("12500"),24,4,"5 hours","/images/packages/yala-dawn-leopard-quest.png","/videos/packages/yala-dawn-leopard-quest.mp4"));
   packages.save(pkg("Elephant & Birdlife Explorer","A relaxed wildlife drive designed for elephant sightings, wetlands and Yala's remarkable birdlife.","Block I Wetland Loop","06:00 - 10:00",new BigDecimal("9800"),30,5,"4 hours","/images/packages/elephant-birdlife-explorer.png","/videos/packages/elephant-birdlife-explorer.mp4"));
   packages.save(pkg("Golden Hour Sunset Safari","Afternoon safari with golden-hour landscapes, waterholes and evening wildlife activity.","Block I - Katagamuwa Route","14:00 - 18:30",new BigDecimal("11000"),30,5,"4.5 hours","/images/packages/golden-hour-sunset-safari.png","/videos/packages/golden-hour-sunset-safari.mp4"));
   packages.save(pkg("Wildlife Photography Drive","Smaller-group experience with slower pacing and photography-friendly stops where park rules allow.","Block I Photography Circuit","05:30 - 11:00",new BigDecimal("15800"),16,3,"5.5 hours","/images/packages/wildlife-photography-drive.png","/videos/packages/wildlife-photography-drive.mp4"));
   packages.save(pkg("Family Discovery Safari","Family-friendly half-day safari with guide briefing, flexible pacing and wildlife interpretation.","Block I Family Route","07:00 - 11:00",new BigDecimal("8500"),28,5,"4 hours","/images/packages/family-discovery-safari.png","/videos/packages/family-discovery-safari.mp4"));
   packages.save(pkg("Full-Day Yala Explorer","A full-day academic prototype package combining multiple habitats with a midday rest period.","Block I Extended Route","05:30 - 17:30",new BigDecimal("22000"),20,4,"12 hours","/images/packages/full-day-yala-explorer.png","/videos/packages/full-day-yala-explorer.mp4"));
  }
  if(vehicles.count()==0){Vehicle v1=new Vehicle();v1.setRegistrationNo("WP-SF-1001");v1.setModel("Toyota Hilux Safari Jeep");v1.setCapacity(6);v1.setStatus(VehicleStatus.AVAILABLE);v1.setDocumentValidUntil(LocalDate.now().plusYears(1));v1.setDriver(driver);vehicles.save(v1);Vehicle v2=new Vehicle();v2.setRegistrationNo("WP-SF-1002");v2.setModel("Mahindra Double Cab Safari");v2.setCapacity(6);v2.setStatus(VehicleStatus.AVAILABLE);v2.setDocumentValidUntil(LocalDate.now().plusMonths(10));vehicles.save(v2);}
  if(bookings.count()==0){SafariPackage p=packages.findAll().get(0);Booking b=new Booking();b.setBookingCode("SL-DEMO01");b.setTourist(tourist);b.setSafariPackage(p);b.setVisitDate(LocalDate.now().plusDays(1));b.setVisitorCount(2);b.setAdultCount(2);b.setChildFiveToElevenCount(0);b.setChildBelowFiveCount(0);b.setGroupLeaderName(tourist.getFullName());b.setContactPhone(tourist.getPhone());b.setEmergencyContact("0779999999");b.setSpecialRequirements("Photography interest");b.setTotalAmount(p.getPricePerPerson().multiply(BigDecimal.valueOf(2)));b.setPaymentStatus(PaymentStatus.PAID);b.setBookingStatus(BookingStatus.CONFIRMED);bookings.save(b);Visitor vv=new Visitor();vv.setBooking(b);vv.setFullName("Demo Tourist");vv.setIdType("NIC");vv.setIdNumber("200012345678");vv.setNationality("Sri Lankan");vv.setAge(22);visitors.save(vv);Payment pay=new Payment();pay.setPaymentCode("PAY-DEMO01");pay.setBooking(b);pay.setAmount(b.getTotalAmount());pay.setMethod(PaymentMethod.CARD);pay.setStatus(PaymentStatus.PAID);pay.setTransactionReference("SIM-DEMO-001");pay.setInvoiceNumber("INV-YALA-DEMO01");pay.setPaidAt(LocalDateTime.now());payments.save(pay);Permit permit=new Permit();permit.setPermitCode("YALA-DEMO01");permit.setBooking(b);permit.setStatus(PermitStatus.APPROVED);permit.setDecisionReason("Demo permit approved and issued.");permit.setDecisionByEmail("park@safarilanka.lk");permit.setDecisionByName("Authorized Park Gate Officer");permit.setDecisionByRole("PARK_OFFICER");permit.setIssuedAt(LocalDateTime.now());permits.save(permit);Vehicle vehicle=vehicles.findAll().get(0);TripAssignment ta=new TripAssignment();ta.setBooking(b);ta.setVehicle(vehicle);ta.setDriver(driver);ta.setGuide(guide);ta.setStatus(AssignmentStatus.ASSIGNED);assignments.save(ta);vehicle.setStatus(VehicleStatus.ASSIGNED);vehicles.save(vehicle);SafariPackage p2=packages.findAll().get(1);Booking b2=new Booking();b2.setBookingCode("SL-DEMO02");b2.setTourist(tourist);b2.setSafariPackage(p2);b2.setVisitDate(LocalDate.now().plusDays(2));b2.setVisitorCount(3);b2.setAdultCount(3);b2.setChildFiveToElevenCount(0);b2.setChildBelowFiveCount(0);b2.setGroupLeaderName(tourist.getFullName());b2.setContactPhone(tourist.getPhone());b2.setEmergencyContact("0778888888");b2.setSpecialRequirements("Family group - child friendly pacing");b2.setTotalAmount(p2.getPricePerPerson().multiply(BigDecimal.valueOf(3)));b2.setPaymentStatus(PaymentStatus.PAID);b2.setBookingStatus(BookingStatus.CONFIRMED);bookings.save(b2);Payment pay2=new Payment();pay2.setPaymentCode("PAY-DEMO02");pay2.setBooking(b2);pay2.setAmount(b2.getTotalAmount());pay2.setMethod(PaymentMethod.MOBILE_WALLET);pay2.setStatus(PaymentStatus.PAID);pay2.setTransactionReference("SIM-DEMO-002");pay2.setInvoiceNumber("INV-YALA-DEMO02");pay2.setPaidAt(LocalDateTime.now());payments.save(pay2);Permit permit2=new Permit();permit2.setPermitCode("YALA-DEMO02");permit2.setBooking(b2);permit2.setStatus(PermitStatus.PENDING);permits.save(permit2);}
 };}
 private User user(UserRepository r,PasswordEncoder e,String name,String email,String pass,Role role,String phone){return r.findByEmailIgnoreCase(email).orElseGet(()->{User u=new User();u.setFullName(name);u.setEmail(email);u.setPassword(e.encode(pass));u.setRole(role);u.setPhone(phone);return r.save(u);});}
 private void setting(SystemSettingRepository r,String k,String v,String d){SystemSetting s=new SystemSetting();s.setSettingKey(k);s.setSettingValue(v);s.setDescription(d);r.save(s);}
 private void ensureSetting(SystemSettingRepository r,String k,String v,String d){if(r.findBySettingKey(k).isEmpty())setting(r,k,v,d);}
 private SafariPackage pkg(String n,String d,String route,String slot,BigDecimal price,int maxV,int maxJ,String dur,String img,String video){SafariPackage p=new SafariPackage();p.setName(n);p.setDescription(d);p.setRouteZone(route);p.setTimeSlot(slot);p.setPricePerPerson(price);p.setAdditionalVehicleFee(price);p.setMaxVisitors(maxV);p.setMaxVehicles(maxJ);p.setDuration(dur);p.setImageUrl(img);p.setVideoUrl(video);p.setPublished(true);return p;}
}
